      support_hero_title: "Support & Kontakt für Train Libre",
      support_hero_copy: "Wenn Sie Fragen haben, auf Probleme stoßen oder einen Fehler in <strong>Train Libre</strong> melden möchten, wenden Sie sich bitte an einen unserer offiziellen Entwickler-Supportkanäle:",
      support_email_title: "Direkter E-Mail-Support",
      support_email_copy: 'Für persönliche oder kontobezogene Anfragen kontaktieren Sie uns direkt unter: <a href="mailto:support@schotte.me">support@schotte.me</a>',
      support_issues_title: "Fehlerverfolgung & Community",
      support_issues_copy: 'Train Libre ist Open Source. Sie können bekannte Fehler direkt durchsuchen oder technische Fehlerberichte in unserem GitHub-Repository einreichen: <a href="https://github.com/rfivesix/train-libre/issues" target="_blank">Fehlerbericht einreichen</a>',
      support_meta_title: "Erwartete Antwortzeit",
